use serde::Deserialize;
use serde_json::Value;

use super::*;

/// Generated by `packages/shared/src/server/pricing-tiers/gatewayCostFixture.test.ts`.
const COST_CASES: &str = include_str!("../../../tests/fixtures/cost-cases.json");

#[derive(Deserialize)]
struct Fixture {
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    usage_details: UsageCostType,
    provided_cost_details: Option<UsageCostType>,
    model_parameters: Value,
    metadata: Value,
    tiers: Vec<PricingTierWithPrices>,
    expected: Expected,
}

#[derive(Deserialize)]
struct Expected {
    cost_details: UsageCostType,
    total_cost: Option<f64>,
    usage_pricing_tier_id: Option<String>,
    usage_pricing_tier_name: Option<String>,
}

fn assert_close(actual: f64, expected: f64, context: &str) {
    let tolerance = 1e-12 * expected.abs().max(1.0);
    assert!(
        (actual - expected).abs() <= tolerance,
        "{context}: {actual} != {expected}"
    );
}

#[test]
fn matches_the_typescript_cost_calculation() {
    let fixture: Fixture = serde_json::from_str(COST_CASES).unwrap();
    assert!(!fixture.cases.is_empty());
    for case in fixture.cases {
        let attributes = PricingAttributes {
            model_parameters: Some(&case.model_parameters),
            metadata: Some(&case.metadata),
        };
        let model = ModelWithPrices {
            model: None,
            pricing_tiers: case.tiers,
        };
        let actual = calculate_model_usage_costs(CalculateModelUsageCostsParams {
            model: &model,
            usage_details: &case.usage_details,
            provided_cost_details: case.provided_cost_details.as_ref(),
            attributes: Some(&attributes),
        });
        let name = &case.name;
        assert_eq!(
            actual.usage_pricing_tier_id, case.expected.usage_pricing_tier_id,
            "{name}"
        );
        assert_eq!(
            actual.usage_pricing_tier_name, case.expected.usage_pricing_tier_name,
            "{name}"
        );
        assert_eq!(
            actual.cost_details.keys().collect::<Vec<_>>(),
            case.expected.cost_details.keys().collect::<Vec<_>>(),
            "{name}"
        );
        for (key, expected) in &case.expected.cost_details {
            assert_close(
                actual.cost_details[key],
                *expected,
                &format!("{name}: {key}"),
            );
        }
        match (actual.total_cost, case.expected.total_cost) {
            (Some(actual), Some(expected)) => assert_close(actual, expected, name),
            (actual, expected) => assert_eq!(actual, expected, "{name}"),
        }
    }
}
